+import { post, sleep } from './http.js';
+
+export interface Order {
+  id: string;
+  lines: Array<{ sku: string; qty: number }>;
+}
+
+/**
+ * Send an order to the payments gateway. The gateway assigns the order id and
+ * has been timing out under load, so retry a few times with backoff.
+ */
+export async function submitOrder(order: Order): Promise<{ id: string }> {
+  for (let attempt = 1; attempt <= 3; attempt++) {
+    try {
+      return await post('/orders', order);
+    } catch (err) {
+      if (attempt === 3) throw err;
+      await sleep(2 ** attempt * 100);
+    }
+  }
+  throw new Error('unreachable');
+}
